#include <string>
#include <vector>

std::vector<std::string> splitCommandLine(const std::string& line)
{
    std::vector<std::string> args;
    std::string current;
    bool inArgument{ false };   // has the current argument started (even if it is still empty)?
    bool inQuotes{ false };
    for (char c : line)
    {
        if (c == '"')
        {
            inQuotes = !inQuotes;
            inArgument = true;
        }
        else if (c == ' ' && !inQuotes)
        {
            if (inArgument) { args.push_back(current); current.clear(); inArgument = false; }
        }
        else
        {
            current += c;
            inArgument = true;
        }
    }
    if (inArgument) args.push_back(current);
    return args;
}

unitTests:
using Args = std::vector<std::string>;
TEST("simple words") { CHECK(splitCommandLine("game.exe -w 800") == Args({ "game.exe", "-w", "800" })); }
TEST("a quoted argument") { CHECK(splitCommandLine("editor.exe --level \"forest 2\"") == Args({ "editor.exe", "--level", "forest 2" })); }
TEST("a quoted program path") { CHECK(splitCommandLine("\"C:\\My Games\\a.exe\" -x") == Args({ "C:\\My Games\\a.exe", "-x" })); }
TEST("quotes in the middle of an argument") { CHECK(splitCommandLine("--name=\"Rook Smith\" go") == Args({ "--name=Rook Smith", "go" })); }
TEST("an empty argument") { CHECK(splitCommandLine("a \"\" b") == Args({ "a", "", "b" })); }
TEST("extra spaces") { CHECK(splitCommandLine("   a    b   ") == Args({ "a", "b" })); }
TEST("nothing at all") { CHECK(splitCommandLine("").empty()); CHECK(splitCommandLine("    ").empty()); }

